/* engines/index.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function fallbackToHtml5(options = {}) {
    const shouldReload = options.reload !== false && !!P.state.current;
    const autoplay = options.autoplay ?? P.pendingAutoplay;
    const startTime = options.startTime ?? P.pendingStart ?? 0;
    P.destroyWaveforms();
    P.state.engine = "html5";
    // A failed default engine stays eligible for retry next visit; an
    // explicitly chosen engine is remembered as the visitor's preference.
    P.hideWaveMode();
    P.setLoading(false);
    P.syncSettingsUI();
    P.saveState();
    // The failed engine may never have set audio.src. Without an explicit
    // reload the bar would show a track that can never start.
    if (shouldReload) P.loadCurrent({ autoplay, startTime, fadeIn: false });
  }

  function loadEngine(url, startAt, autoplay) {
    P.setLoading(true, 0);
    switch (P.state.engine) {
      case "wavesurfer": return P.createWaveSurfer(url, startAt, autoplay);
      case "peaks": return P.createPeaks(url, startAt, autoplay);
      case "howler": return P.createHowler(url, startAt, autoplay);
      case "waviz": return P.createWaviz(url, startAt, autoplay);
      case "mediaelement": return P.createMediaElement(url, startAt, autoplay);
      case "amplitude": return P.createAmplitude(url, startAt, autoplay);
      case "aplayer": return P.createAPlayer(url, startAt, autoplay);
      case "jplayer": return P.createJPlayer(url, startAt, autoplay);
      default:
        P.hideWaveMode();
        P.audio.src = url;
        P.audio.load();
        if (autoplay) P.attemptPlay();
        return Promise.resolve(true);
    }
  }

  function setEngine(name) {
    if (!P.ENGINES.includes(name)) return;
    if (name === P.state.engine) {
      // Selecting the engine that is already active is still an explicit
      // choice — e.g. confirming HTML5 after the default engine failed.
      if (!P.state.engineExplicit) {
        P.state.engineExplicit = true;
        P.saveState();
        P.notify("settings");
      }
      return;
    }
    const wasPlaying = !P.audio.paused;
    const time = P.audio.currentTime || P.state.time || 0;

    P.destroyWaveforms();
    P.state.engine = name;
    P.state.engineExplicit = true;

    if (P.state.current) P.loadCurrent({ autoplay: wasPlaying, startTime: time, fadeIn: false });
    else { P.hideWaveMode(); P.cancelPreload(); }
    P.syncSettingsUI();
    P.saveState();
    P.notify("engine");
  }
  Object.assign(P, { fallbackToHtml5, loadEngine, setEngine });
}
